<script>(()=>{const format=(n)=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:2}).format(n);const c=document.getElementById('giftRate'),v=document.getElementById('faceValue'),u=document.getElementById('giftCurrency'),q=document.getElementById('giftQuote');function f(){const o=c?.selectedOptions[0],r=Number(o?.dataset.rate)||0,a=Number(v?.value)||0;if(u)u.textContent=o?.dataset.currency||'currency';if(q)q.textContent=format(a*r)}c?.addEventListener('change',f);v?.addEventListener('input',f);f();const sc=document.getElementById('saleRate'),sv=document.getElementById('saleValue'),su=document.getElementById('saleCurrency'),sq=document.getElementById('saleQuote');function sf(){const o=sc?.selectedOptions[0],r=Number(o?.dataset.rate)||0,a=Number(sv?.value)||0;if(su)su.textContent=o?.dataset.currency||'currency';if(sq)sq.textContent=format(a*r)}sc?.addEventListener('change',sf);sv?.addEventListener('input',sf);sf()})();</script>
